        {
          "function": "structure_summary",
          "feature": "alkali_alkaline_site_fraction",
          "physical_role": "Fraction of strongly electropositive cations that can donate electrons to interstitial sites; higher values favor electride formation."
        },
        {
          "function": "structure_summary",
          "feature": "pauling_electronegativity__min",
          "physical_role": "Lowest Pauling electronegativity in the structure; low minima indicate highly reducing elements that leave electrons unbound."
        },
        {
          "function": "structure_summary",
          "feature": "volume_per_atom_A3",
          "physical_role": "Cell volume normalised by atom count; higher values signal overall lattice openness and the presence of empty cages."
        },
        {
          "function": "electron_count_hypotheses",
          "feature": "total_assignment_count",
          "physical_role": "Number of viable oxidation\u2011state assignments; a low count implies excess electrons that cannot be neutralised, a key electride signature."
        },
        {
          "function": "cavity_geometry",
          "feature": "sampled_grid_clearance_statistics_A__mean",
          "physical_role": "Mean sampled clearance across the grid; negative mean reflects generally tight interstitial space, a pattern observed in cage\u2011type electrides."
        },
        {
          "function": "cavity_geometry",
          "feature": "sampled_grid_clearance_statistics_A__std",
          "physical_role": "Standard deviation of sampled clearances; high variance captures heterogeneity of void sizes, distinguishing structures with a few large cages among tighter regions."
        },
        {
          "function": "cavity_geometry",
          "feature": "candidate_count_before_output_limit",
          "physical_role": "Number of void\u2011center candidates before truncation; a larger count indicates many accessible interstitial sites, serving as a proxy for rich void networks as advocated in the descriptor framework of arXiv:2605.11724."
        }
      ],
      "reasoning": "Features 1\u20112 encode the electropositive chemistry identified in Li6P and other electride studies. Feature 3 captures bulk\u2011scale openness (cage\u2011like frameworks) highlighted for Li8Au and related electrides. Feature 4 directly measures the excess\u2011electron condition via oxidation\u2011state combinatorics. Features 5\u20116 quantify both the average size and heterogeneity of interstitial voids, addressing the redundancy between max_clearance_A and mean clearance observed previously while adding complementary variance information. Feature 7 provides a count\u2011based proxy for void\u2011network richness, aligning with the high\u2011throughput descriptor strategy proposed in arXiv:2605.11724.  Together these seven descriptors are physically distinct, interpretable, and expected to improve classification performance.",
